#!/usr/bin/env bash
# Question 17: Pods cannot be created in ${Q17_NS}. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "${Q17_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q17_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q17_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl label namespace "${Q17_NS}" webhook-lab=true --overwrite
kubectl apply -f - <<EOF
apiVersion: apps/v1
kind: Deployment
metadata:
  name: ${Q17_APP}
  namespace: ${Q17_NS}
spec:
  replicas: 0
  selector:
    matchLabels: { app: ${Q17_APP} }
  template:
    metadata:
      labels: { app: ${Q17_APP} }
    spec:
      containers:
        - name: web
          image: nginx:1.27-alpine
          ports: [{ containerPort: 80 }]
          readinessProbe:
            httpGet: { path: /, port: 80 }
            periodSeconds: 5
EOF
kubectl -n "${Q17_NS}" get deployment "${Q17_APP}" -o jsonpath='{.metadata.uid}' > "/var/tmp/cka-q17.uid"
chmod 644 "/var/tmp/cka-q17.uid"

case "${Q17_FAULT}" in
  webhook-orphan-fail)
    kubectl apply -f - <<< '{"apiVersion":"admissionregistration.k8s.io/v1","kind":"ValidatingWebhookConfiguration","metadata":{"name":"orphan-validate"},"webhooks":[{"name":"orphan.cka.lab","failurePolicy":"Fail","sideEffects":"None","timeoutSeconds":3,"admissionReviewVersions":["v1"],"clientConfig":{"service":{"name":"missing-webhook-svc","namespace":"'"${Q17_NS}"'","path":"/validate"},"caBundle":"LS0tLS0tRU5EIENFUlRJRklDQVRFLS0tLS0t"},"rules":[{"apiGroups":[""],"apiVersions":["v1"],"operations":["CREATE"],"resources":["pods"],"scope":"Namespaced"}],"namespaceSelector":{"matchLabels":{"webhook-lab":"true"}}}]}'
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac

kubectl -n "${Q17_NS}" scale "deployment/${Q17_APP}" --replicas=2
notready=0
for _ in $(seq 1 15); do
  states="$(kubectl -n "${Q17_NS}" get pods -l "app=${Q17_APP}" -o jsonpath='{range .items[*]}{.status.phase} {.status.conditions[?(@.type=="Ready")].status} {.status.conditions[?(@.type=="PodScheduled")].status} {.status.containerStatuses[0].state.waiting.reason} {.status.containerStatuses[0].restartCount}{"\n"}{end}' 2>/dev/null)"
  if grep -qE '(ErrImagePull|ImagePullBackOff|CrashLoopBackOff|CreateContainerConfigError|CreateContainerError|RunContainerError)|[1-9][0-9]*$|^[A-Za-z]+ [A-Za-z]* False' <<< "$states"; then break; fi
  if kubectl -n "${Q17_NS}" get events --field-selector reason=FailedMount -o name 2>/dev/null | grep -q .; then break; fi
  if grep -qE '^Running False' <<< "$states"; then
    notready=$((notready + 1))
    (( notready >= 3 )) && break
  else
    notready=0
  fi
  sleep 2
done
[[ "$(kubectl -n "${Q17_NS}" get deployment "${Q17_APP}" -o jsonpath='{.status.readyReplicas}')" != 2 ]] || { echo "${Q17_APP} is still healthy" >&2; exit 1; }
